import stim
from surface_sim.models import CircuitNoiseModel
from ..code_params import BB_codes_dict

class BBCircuitParams:
    """
    A helper class to generate the circuits simulated in arXiv:2407.16336.
    """
    def __init__(
        self,
        name,
        circuit_type,
        bb_params,
        homomorphism_str=None,
        circuit=stim.Circuit(),
    ):
        """
        Initialises a BBCircuitParams object.

        Arguments:
            name is a string, can be whatever you want.
            circuit_type is a string, either "IBM", "standard_morphing", or "swap2_morphing", depending on the type of circuit to generate.
                "IBM" uses the BBParams.get_IBM_XZ_memory_circuit method to generate the circuit.
                "standard_morphing" uses the Abelian2BGAParams.get_standard_morphing_specifications method.
                "swap2_morphing" uses the BBParams.get_swap2_morphing_specifications method.
            bb_params is a BBParams object representing the end-cycle code of the IBM circuit, or mid-cycle code of the morphing circuit.
            homomorphism_str is a Str "x", "y", or "xy" defining the morphing circuit, representing the homomorphism_actions [[1],[0]], [[0],[1]], and
                [[1],[1]], respectively.
            circuit is a stim.Circuit that is generated by the compile_circuit method of this class.

        """
        self.name = name
        self.circuit_type = circuit_type
        self.bb_params = bb_params
        self.homomorphism_str = homomorphism_str
        self.circuit = circuit

    def __str__(self):
        return self.name

    def compile_circuit(
        self,
        noise_setup,
        T,
        noise_model_generator=lambda qubit_dictionary, noise_setup: CircuitNoiseModel(
            qubit_dictionary, noise_setup
        ),
    ):
        """
        Returns a stim circuit for a memory experiment for the bb_params, circuit_type, and homomorphism_str specified.
        The memory experiment contains observables for all the logical operators of the code (both X and Z). It begins and ends with one round of
            ideal QEC, with T rounds of noisy QEC in between.
        
        Arguments:
            noise_setup is a surface_sim.Setup object that sets up the noise model to be used in the circuit.
            T is the number of noisy QEC rounds in the memory experiment.
            noise_model_generator is a function that takes two arguments: a qubit dictionary, and a noise setup, and returns a surface_sim.Model object
                that defines the noise model of the memory experiment.
        
        Returns:
            A stim circuit for the memory experiment.
        """
        if self.circuit_type == "IBM":
            self.circuit = self.bb_params.get_IBM_XZ_memory_circuit(
                noise_setup, T, noise_model_generator=noise_model_generator
            )
        elif self.circuit_type in ["standard_morphing", "swap2_morphing"]:
            specification = self._get_specifications()
            self.circuit = specification.get_morphing_XZ_memory_circuit(
                noise_setup, T, noise_model_generator=noise_model_generator
            )
        else:
            raise ValueError(
                """circuit_type must be "IBM", "standard_morphing", or "swap2_morphing"."""
            )

    def _get_specifications(self):
        if self.circuit_type == "IBM":
            return None
        elif self.circuit_type == "standard_morphing":
            return self.bb_params.get_standard_morphing_specifications(
                self.homomorphism_str
            )
        elif self.circuit_type == "swap2_morphing":
            return self.bb_params.get_swap2_morphing_specifications(
                self.homomorphism_str
            )
        else:
            raise ValueError(
                """run_dict.circuit.circuit_type must be "IBM" or "middle_out"."""
            )

    def get_sampler_dem(
        self,
        noise_setup,
        T,
        noise_model_generator=lambda qubit_dictionary, noise_setup: CircuitNoiseModel(
            qubit_dictionary, noise_setup
        ),
        separate_XZ=False,
    ):
        """
        Returns a stim.CompiledDEMSampler and stim.DetectorErrorModel that can be given to circuit_functions.sample_logical_flips to run the simulation.
        
        Arguments:
            noise_setup is a surface_sim.Setup object that sets up the noise model to be used in the circuit.
            T is the number of noisy QEC rounds in the memory experiment.
            noise_model_generator is a function that takes two arguments: a qubit dictionary, and a noise setup, and returns a surface_sim.Model object
                that defines the noise model of the memory experiment.
            separate_XZ is a bool, if set to True then separate detector error models for the X- and Z-sectors will be returned.
        
        Returns:
            If separate_XZ = False, a tuple (sampler, dem, {}) where sampler is the stim.CompiledDEMSampler and dem is the stim.DetectorErrorModel.
            If separate_XZ = True, a tuple (sampler, dem_dict, indices_dict) where sampler is the stim.CompiledDEMSampler, dem_dict is a dictionary with
                keys "X" and "Z" and items corresponding to the X- and Z-dem's respectively, and indices_dict is a dictionary with keys "X" and "Z" and
                items that list the indices of the X-detectors and Z-detectors in the dem. This output can be fed directly into
                circuit_functions.sample_logical_flips with separate_XZ = True.
        """
        if self.circuit == stim.Circuit():
            self.compile_circuit(
                noise_setup, T, noise_model_generator=noise_model_generator
            )

        if separate_XZ:
            sampler = self.circuit.compile_detector_sampler()
            dem_dict, indices_dict = separate_XZ_dem_from_circuit(self.circuit)
            return sampler, dem_dict, indices_dict
        else:
            sampler = self.circuit.compile_detector_sampler()
            dem = self.circuit.detector_error_model()
            return sampler, dem, {}

